import AppKit
import CoreGraphics
import ScreenCaptureKit

// T1 spike (issue #132): does capturing OUR OWN window need Screen Recording (TCC) consent?
//
// SCShareableContent.h:151 documents `currentProcess` as returning content available to capture
// "without user consent via TCC" — but that sentence is about the *enumeration*. Whether
// SCScreenshotManager will then hand back real pixels is inference, so measure it.
//
// Runs as its own ad-hoc-signed bundle with its own bundle id, whose ScreenCapture grant is reset
// before launch, so it cannot inherit a grant from a parent terminal. Logs to a file because a
// LaunchServices-launched app has no stdout.

let logURL = URL(fileURLWithPath: "/tmp/sck-spike.log")
var lines: [String] = []
func log(_ s: String) {
  lines.append(s)
  try? lines.joined(separator: "\n").write(to: logURL, atomically: true, encoding: .utf8)
}

/// Distinctive, definitely-non-uniform content, so "did we get real pixels" is answerable.
final class PatternView: NSView {
  override func draw(_ dirtyRect: NSRect) {
    let colors: [NSColor] = [.systemRed, .systemBlue, .systemGreen, .systemOrange]
    let w = bounds.width / 2, h = bounds.height / 2
    for (i, c) in colors.enumerated() {
      c.setFill()
      NSRect(x: CGFloat(i % 2) * w, y: CGFloat(i / 2) * h, width: w, height: h).fill()
    }
    let text = "SCK SPIKE" as NSString
    text.draw(
      at: NSPoint(x: 40, y: bounds.midY),
      withAttributes: [
        .font: NSFont.monospacedSystemFont(ofSize: 48, weight: .bold),
        .foregroundColor: NSColor.white,
      ])
  }
}

/// How many distinct colours a sparse sample of the image contains. 1 ⇒ a blank/black frame, which is
/// what a TCC-denied or off-Space capture looks like; the pattern above should give several.
func distinctColours(_ image: CGImage) -> Int {
  guard let data = image.dataProvider?.data, let bytes = CFDataGetBytePtr(data) else { return 0 }
  let bpr = image.bytesPerRow, bpp = image.bitsPerPixel / 8
  var seen = Set<UInt32>()
  for y in stride(from: 0, to: image.height, by: max(1, image.height / 40)) {
    for x in stride(from: 0, to: image.width, by: max(1, image.width / 40)) {
      let o = y * bpr + x * bpp
      guard o + 3 < CFDataGetLength(data) else { continue }
      let px =
        UInt32(bytes[o]) << 24 | UInt32(bytes[o + 1]) << 16 | UInt32(bytes[o + 2]) << 8
        | UInt32(bytes[o + 3])
      seen.insert(px)
    }
  }
  return seen.count
}

final class Delegate: NSObject, NSApplicationDelegate {
  var window: NSWindow!

  func applicationDidFinishLaunching(_ note: Notification) {
    window = NSWindow(
      contentRect: NSRect(x: 200, y: 200, width: 820, height: 520),
      styleMask: [.titled, .closable], backing: .buffered, defer: false)
    window.title = "SCK Spike Window"
    window.contentView = PatternView()
    // orderFrontRegardless, NOT activate: also tests the plan's claim that a window which isn't
    // frontmost still captures.
    window.orderFrontRegardless()

    Task { await self.run() }
  }

  func run() async {
    // MUST NOT call CGRequestScreenCaptureAccess — that prompts, and a prompt would both block and
    // change the very state we're measuring. Preflight never prompts.
    let preflight = CGPreflightScreenCaptureAccess()
    log("bundleID: \(Bundle.main.bundleIdentifier ?? "nil")")
    log("CGPreflightScreenCaptureAccess: \(preflight)   <- false means NO grant for this identity")

    do {
      let content = try await SCShareableContent.currentProcess
      log("currentProcess windows: \(content.windows.count), displays: \(content.displays.count)")
      for w in content.windows {
        log("  window id=\(w.windowID) title=\(w.title ?? "nil") frame=\(w.frame) onScreen=\(w.isOnScreen)")
      }

      let number = CGWindowID(window.windowNumber)
      guard let mine = content.windows.first(where: { $0.windowID == number }) else {
        log("RESULT: FAIL — our own window (id \(number)) is absent from currentProcess content")
        finish()
        return
      }

      let filter = SCContentFilter(desktopIndependentWindow: mine)
      log("filter.contentRect: \(filter.contentRect)  pointPixelScale: \(filter.pointPixelScale)")
      log("NSWindow.frame: \(window.frame)  backingScaleFactor: \(window.backingScaleFactor)")

      let config = SCStreamConfiguration()
      // Strictly proportional sizing, per the review: width/height are the only knobs and a mismatched
      // aspect letterboxes, which would silently misalign every crop.
      let scale = CGFloat(filter.pointPixelScale)
      config.width = Int((filter.contentRect.width * scale).rounded())
      config.height = Int((filter.contentRect.height * scale).rounded())
      config.showsCursor = false
      config.ignoreShadowsSingleWindow = true
      config.ignoreGlobalClipSingleWindow = true
      config.captureResolution = .best

      let image = try await SCScreenshotManager.captureImage(
        contentFilter: filter, configuration: config)
      let colours = distinctColours(image)
      log("captured image: \(image.width)x\(image.height) bpp=\(image.bitsPerPixel)")
      log("derived scaleX: \(CGFloat(image.width) / window.frame.width)")
      log("derived scaleY: \(CGFloat(image.height) / window.frame.height)")
      log("distinct sampled colours: \(colours)")

      if let dest = CGImageDestinationCreateWithURL(
        URL(fileURLWithPath: "/tmp/sck-spike.png") as CFURL, "public.png" as CFString, 1, nil)
      {
        CGImageDestinationAddImage(dest, image, nil)
        CGImageDestinationFinalize(dest)
        log("wrote /tmp/sck-spike.png")
      }

      let real = colours > 2
      log(
        "RESULT: \(real ? "PASS" : "FAIL") — capture \(real ? "returned real pixels" : "was blank/uniform")"
          + " with preflight=\(preflight)")
    } catch {
      log("RESULT: FAIL — \(error) (\((error as NSError).domain) \((error as NSError).code))")
    }
    finish()
  }

  func finish() {
    log("done")
    NSApp.terminate(nil)
  }
}

