  let count: Int
  private let theme = ThemeService.shared

  var body: some View {
    if count > 0 {
      Circle()
        .fill(theme.tokens.accent)
        .frame(width: 7, height: 7)
        .accessibilityLabel("Unread notifications")
    }
  }
}
