import XCTest

@testable import Workroom

/// `WorkroomLabel` (issue #132, T7): the one formatter behind the workroom tab chip's tooltip, the
/// split pane title bar's, a notification's origin line, and the quick-switcher rail. Four surfaces
/// used to build this string themselves and two had already drifted on the separator, so these tests
/// pin the shared format, the root/branch distinction, and the rail's prefix-dropping rule (D12).
@MainActor
final class WorkroomLabelFormatTests: XCTestCase {

  private func makeStore(_ projects: [Project]) -> AppStore {
    let store = AppStore()
    store.terminals.makeView = { _, cwd, _ in GhosttySurfaceView(workingDirectory: cwd) }
    store.projects = projects
    return store
  }

  private func project(_ path: String, workrooms: [String]) -> Project {
    Project(
      path: path, vcs: "git",
      workrooms: workrooms.map {
        Workroom(name: $0, path: "\(path)/\($0)", vcsName: "workroom/\($0)", warnings: [])
      })
  }

  // MARK: Formatting

  func testFullTitleFormat() {
    XCTAssertEqual(WorkroomLabel(project: "platform", workroom: "fix-auth").full, "platform / fix-auth")
    XCTAssertEqual(WorkroomLabel(project: "platform").full, "platform", "a root shows only the project")
    XCTAssertEqual(
      WorkroomLabel(project: "platform", branch: "main").full, "platform",
      "a branch is state, never part of the title")
  }

  func testFullTitleMatchesNotificationSourceFormat() {
    var fox = Workroom(name: "fox", path: "/p/fox", vcsName: "workroom/fox", warnings: [])
    fox.label = "Auth"
    let projects = [Project(path: "/p", vcs: "git", workrooms: [fox])]
    // The regression this extraction exists to prevent: the chip's tooltip and the notification
    // origin line must be one format. Before T7 the chip rendered "p/Auth" and this rendered "p / Auth".
    XCTAssertEqual(
      AppStore.notificationSource(forTargetID: TerminalTarget.workroomID(project: "/p", name: "fox"), in: projects),
      WorkroomLabel(project: "p", workroom: "Auth").full)
  }

  func testDistinguishingSegment() {
    XCTAssertEqual(WorkroomLabel(project: "platform", workroom: "fix-auth").distinguishing, "fix-auth")
    XCTAssertEqual(
      WorkroomLabel(project: "platform", branch: "main").distinguishing, "platform",
      "a root is distinguished by its project, NOT its branch")
  }

  // MARK: Rail titles (D12)

  func testRailTitlesDropASharedProjectPrefix() {
    let labels = [
      WorkroomLabel(project: "workroom", workroom: "partitioned-crescent"),
      WorkroomLabel(project: "workroom", workroom: "partitioned-cascade"),
      WorkroomLabel(project: "workroom"),
    ]
    XCTAssertEqual(
      WorkroomLabel.railTitles(labels),
      ["partitioned-crescent", "partitioned-cascade", "workroom"],
      "one project on the rail ⇒ the prefix distinguishes nothing and costs width")
  }

  func testRailTitlesKeepTheProjectWhenItDisambiguates() {
    let labels = [
      WorkroomLabel(project: "workroom", workroom: "fox"),
      WorkroomLabel(project: "platform", workroom: "fox"),
    ]
    XCTAssertEqual(
      WorkroomLabel.railTitles(labels), ["workroom / fox", "platform / fox"],
      "two same-named workrooms across projects must not both read \"fox\"")
  }

  func testRailTitlesEdgeCases() {
    XCTAssertEqual(WorkroomLabel.railTitles([]), [])
    XCTAssertEqual(
      WorkroomLabel.railTitles([WorkroomLabel(project: "p", workroom: "fox")]), ["fox"],
      "a single card needs no prefix")
    XCTAssertEqual(
      WorkroomLabel.railTitles([
        WorkroomLabel(project: "p", workroom: "fox"), WorkroomLabel(project: "p"),
      ]).count, 2, "index-aligned with the input")
  }

  // MARK: Resolution — AppStore.label(for:)

  func testLabelResolvesWorkroomDisplayName() {
    let store = makeStore([project("/Users/me/platform", workrooms: ["fox"])])
    let sid = SidebarID.workroom(project: "/Users/me/platform", name: "fox")
    XCTAssertEqual(store.label(for: sid), WorkroomLabel(project: "platform", workroom: "fox"))
    // A relabel (issue #41) must show through — the resolver reads displayName, not the sid's name.
    store.setWorkroomLabel(store.projects[0].workrooms[0], in: store.projects[0], to: "Auth")
    XCTAssertEqual(store.label(for: sid).workroom, "Auth")
    XCTAssertEqual(store.label(for: sid).full, "platform / Auth")
  }

  func testLabelForRootCarriesBranchButNotInTheTitle() {
    let store = makeStore([project("/Users/me/platform", workrooms: [])])
    let sid = SidebarID.root(project: "/Users/me/platform")
    // Unresolved: RootPresentation.make renders "root" as a PLACEHOLDER — it must not pose as a branch.
    XCTAssertNil(store.label(for: sid).branch, "an unresolved ref has no branch")
    XCTAssertEqual(store.label(for: sid).full, "platform")
    store.rootRefs["/Users/me/platform"] = RootRef(branch: "main", kind: .branch)
    XCTAssertEqual(store.label(for: sid).branch, "main")
    XCTAssertNil(store.label(for: sid).workroom)
    XCTAssertEqual(store.label(for: sid).full, "platform", "branch stays out of the title")
  }

  func testLabelForUnknownProjectDegradesToEmptyProject() {
    let store = makeStore([])
    XCTAssertEqual(
      store.label(for: .workroom(project: "/gone", name: "fox")),
      WorkroomLabel(project: "gone", workroom: "fox"),
      "the path's last component is used even when the project isn't loaded (mid-reload race)")
  }
}

import Foundation

/// Pure decision core for one quick-switcher session (issue #132, stage 2). Modelled on
/// `EdgeRevealReducer`: no timers, no AppKit, no SwiftUI — the controller owns the reveal timer, the
/// modifier poll and the panel, and performs whatever `Effect` comes back.
///
/// ```
///                     ┌──────────────────── cancel(escape|deactivated|empty|timeout) ──────┐
///                     │                                                                    ▼
///    idle ──open(count>1)──▶ pending ──revealTimerFired(250ms)──▶ revealed ──released──▶ idle
///     ▲  │                     │  │                                 │  ▲                  │
///     │  └─open(count<=1)─▶ idle  └──step──▶ revealed (immediate)    │  └─point/step (±)   │
///     │                                                             └────commit(index) ────┘
///     └──────────── every event while .idle is a no-op ◀── (click commit, then release)
/// ```
///
/// Four rules carry the weight, each with a test:
/// - **`.idle` swallows everything.** A mouse click commits and goes idle; the modifier release that
///   inevitably follows must not commit a second time.
/// - **`step` while `.pending` reveals immediately** — ⌥Tab⌥Tab means "show me the rail now".
/// - **`revealTimerFired` outside `.pending` is a no-op**, so a timer that fires after a fast release
///   can't resurrect a finished session.
/// - **`itemsChanged(0)` ends without committing**; `> 0` clamps the cursor rather than dangling past
///   the end.
///
/// Not modelled here: the VoiceOver path (D16). With VoiceOver running the controller never opens a
/// session at all — it commits through the stage-1 `QuickSwitcher.step` and announces — so there is no
/// unfocusable panel to narrate and no announcement queue to land after the commit.
struct QuickSwitcherReducer: Equatable {

  enum Phase: Equatable {
    case idle
    /// Modifier still held, cursor has moved, panel not shown yet. A release here is the tap-flip.
    case pending
    /// The rail is on screen.
    case revealed
  }

  enum Cancel: Equatable {
    /// Escape pressed.
    case escape
    /// The app lost active state (⌘Tab away, another app clicked).
    case deactivated
    /// Every item went away.
    case empty
    /// The hard ceiling — a stuck modifier must not leave the rail up forever.
    case timeout
  }

  enum Event: Equatable {
    /// A trigger keypress with no session live. `count` is the frozen item count.
    case open(kind: QuickSwitcherKind, count: Int, reverse: Bool)
    /// Another trigger press, or ←/→.
    case step(reverse: Bool)
    /// The pointer moved onto a card. Ignored until `armHover` (D17).
    case point(index: Int)
    /// Real pointer movement seen since the reveal — hover may now steer the cursor (D17).
    case armHover
    case revealTimerFired
    /// A click on a card. `nil` means "commit whatever the cursor is on".
    case commit(index: Int?)
    case modifierReleased
    case cancel(Cancel)
    /// The item list changed under us (a window closed, a pane died).
    case itemsChanged(count: Int)
  }

  enum Effect: Equatable {
    case none
    /// Start the reveal timer. The panel stays hidden — a quick tap must not flash it.
    case armReveal
    /// Show the panel (and render the current cursor).
    case reveal
    /// The cursor moved while already revealed — scroll it into view.
    case moveCursor(Int)
    /// Session over. `commit` is the index to switch to, or nil to leave the selection alone.
    case end(commit: Int?)
  }

  /// How long the modifier must stay held before the rail appears. 250 ms, not 180: at 180 a chorded
  /// tap flashes the panel. (The 180 ms in `EdgeRevealSidebar` is a *hide* debounce, not a reveal
  /// delay — reading it as precedent was a misread.)
  static let revealDelay: Duration = .milliseconds(250)

  /// The ceiling on one session, so a modifier the poll never sees released can't strand the rail.
  static let sessionCeiling: Duration = .seconds(10)

  private(set) var phase: Phase = .idle
  private(set) var kind: QuickSwitcherKind = .workrooms
  private(set) var count = 0
  private(set) var cursor = 0
  /// False from `open` until `armHover`: the panel is centred, so it can appear *under* a stationary
  /// pointer, and an unarmed `.onHover` would move the selection to whatever card landed there —
  /// release would then commit a destination the user never chose (D17).
  private(set) var hoverArmed = false

  var isRevealed: Bool { phase == .revealed }
  var isLive: Bool { phase != .idle }

  mutating func handle(_ event: Event) -> Effect {
    switch event {
    case .open(let kind, let count, let reverse):
      // Not a fresh session: an `open` arriving mid-session is another step (holding ⌥ and tapping Tab
      // again re-enters through the same monitor branch).
      if phase != .idle { return handle(.step(reverse: reverse)) }
      // Nothing to switch to — the monitor passes the key through instead, so ⌃Tab still reaches a TUI.
      guard count > 1 else { return .none }
      self.kind = kind
      self.count = count
      cursor = Self.destination(from: 0, count: count, reverse: reverse)
      hoverArmed = false
      phase = .pending
      return .armReveal

    case .step(let reverse):
      guard phase != .idle else { return .none }
      cursor = Self.destination(from: cursor, count: count, reverse: reverse)
      // A second trigger press while still pending means the user wants to see the choices now,
      // without waiting out the rest of the reveal delay.
      if phase == .pending {
        phase = .revealed
        return .reveal
      }
      return .moveCursor(cursor)

    case .point(let index):
      guard phase == .revealed, hoverArmed, index != cursor, count > 0 else { return .none }
      guard (0..<count).contains(index) else { return .none }
      cursor = index
      return .moveCursor(cursor)

    case .armHover:
      guard phase != .idle else { return .none }
      hoverArmed = true
      return .none

    case .revealTimerFired:
      // A stale timer from a session that already ended (or one already revealed by a step).
      guard phase == .pending else { return .none }
      phase = .revealed
      return .reveal

    case .commit(let index):
      guard phase != .idle else { return .none }
      let target = index ?? cursor
      end()
      guard (0..<count).contains(target) else { return .end(commit: nil) }
      return .end(commit: target)

    case .modifierReleased:
      // Already committed by a click — this is the release that follows it, and must do nothing.
      guard phase != .idle else { return .none }
      let target = cursor
      end()
      return .end(commit: target)

    case .cancel:
      guard phase != .idle else { return .none }
      end()
      return .end(commit: nil)

    case .itemsChanged(let newCount):
      guard phase != .idle else { return .none }
      guard newCount > 0 else {
        end()
        return .end(commit: nil)
      }
      count = newCount
      let clamped = min(cursor, newCount - 1)
      guard clamped != cursor else { return .none }
      cursor = clamped
      return phase == .revealed ? .moveCursor(cursor) : .none
    }
  }

  private mutating func end() {
    phase = .idle
    count = 0
    cursor = 0
    hoverArmed = false
  }

  /// One step through the MRU list, wrapping. Shares `AppStore.wrapped` with the two tab cyclers
  /// (T6) so all three agree on the wrap.
  nonisolated static func destination(from current: Int, count: Int, reverse: Bool) -> Int {
    AppStore.wrapped(index: current, by: reverse ? -1 : 1, count: count)
  }
}

