import AppKit

// Probe: does a borderless, non-opaque NSPanel with `hasShadow = true` cast a shadow that follows its
// rounded GLASS content, or a square shadow around the whole frame? Mirrors SwitcherPanel exactly.
final class Probe: NSObject, NSApplicationDelegate {
  var panel: NSPanel!

  func applicationDidFinishLaunching(_ note: Notification) {
    let w: CGFloat = 520
    let h: CGFloat = 128
    panel = NSPanel(
      contentRect: NSRect(x: 0, y: 0, width: w, height: h),
      styleMask: [.nonactivatingPanel, .borderless], backing: .buffered, defer: false)
    panel.isFloatingPanel = true
    panel.level = .floating
    panel.isOpaque = false
    panel.backgroundColor = .clear
    panel.hasShadow = true
    panel.animationBehavior = .none

    let host = NSView(frame: NSRect(x: 0, y: 0, width: w, height: h))
    if #available(macOS 26.0, *) {
      let glass = NSGlassEffectView(frame: host.bounds)
      glass.cornerRadius = 20
      glass.style = .regular
      glass.autoresizingMask = [.width, .height]
      host.addSubview(glass)
    }
    panel.contentView = host

    // Put it somewhere predictable and print the frame so the crop is exact.
    let screen = NSScreen.main!.frame
    let origin = CGPoint(x: (screen.width - w) / 2, y: (screen.height - h) / 2)
    panel.setFrame(NSRect(origin: origin, size: NSSize(width: w, height: h)), display: false)
    panel.orderFrontRegardless()
    panel.invalidateShadow()

    print("FRAME \(panel.frame.origin.x) \(panel.frame.origin.y) \(w) \(h)")
    print("SCREEN \(screen.width) \(screen.height)")
    fflush(stdout)
  }
}

let app = NSApplication.shared
let probe = Probe()
app.delegate = probe
app.setActivationPolicy(.accessory)
app.run()

