struct RailGlassBackground: NSViewRepresentable {
  var cornerRadius: CGFloat = 20

  func makeNSView(context: Context) -> ShadowHost {
    let host = ShadowHost()
    host.cornerRadius = cornerRadius
    host.addSubview(material())
    return host
  }

  func updateNSView(_ host: ShadowHost, context: Context) {
    host.cornerRadius = cornerRadius
    if #available(macOS 26.0, *), let glass = host.subviews.first as? NSGlassEffectView {
      glass.cornerRadius = cornerRadius
      return
    }
    host.subviews.first?.layer?.cornerRadius = cornerRadius
  }

  private func material() -> NSView {
    if #available(macOS 26.0, *) {
      let glass = NSGlassEffectView()
      glass.cornerRadius = cornerRadius
      // `.regular` rather than `.clear`: the rail carries text over arbitrary windows and wallpapers, and
      // `.clear` leaves too little separation for a 12pt subtitle to survive a busy backdrop.
      glass.style = .regular
      glass.autoresizingMask = [.width, .height]
      return glass
    }
    let effect = NSVisualEffectView()
    effect.material = .hudWindow
    effect.blendingMode = .behindWindow
    effect.state = .active  // NOT `.followsWindowActiveState`: this panel is never the key window
    effect.autoresizingMask = [.width, .height]
    effect.wantsLayer = true
    effect.layer?.cornerRadius = cornerRadius
    effect.layer?.cornerCurve = .continuous
    effect.layer?.masksToBounds = true
    return effect
  }

  /// Carries the rail's drop shadow, and nothing else — the material rides inside it.
  ///
  /// The shadow is a **layer shadow with an explicit `shadowPath`**, for two reasons. The window can't
  /// cast it: a borderless non-opaque panel produces no system shadow whatsoever (measured — zero
  /// darkening at every distance with `hasShadow = true`, glass content or solid fill alike). And an
  /// implicit layer shadow is derived from the layer's own alpha, which for a glass material is not
  /// something to bet on; a `shadowPath` renders the rail's rounded rect regardless of what the material
  /// contributes. `SwitcherRailLayout.shadowMargin` is the room this needs inside the window.
  final class ShadowHost: NSView {
    var cornerRadius: CGFloat = 20 {
      didSet { needsLayout = true }
    }

    override init(frame frameRect: NSRect) {
      super.init(frame: frameRect)
      wantsLayer = true
      layer?.shadowColor = NSColor.black.cgColor
      // Broad and low-contrast: the shadow's job is to lift the glass off whatever is behind it, not to
      // draw an edge. A tight, dark one reads as a hard border around the rail.
      layer?.shadowOpacity = 0.28
      layer?.shadowRadius = 16
      // Layer geometry here is y-up (the view is not flipped), so downward is negative.
      layer?.shadowOffset = CGSize(width: 0, height: -5)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) { fatalError("not used") }

    override func layout() {
      super.layout()
      subviews.first?.frame = bounds
      layer?.shadowPath = CGPath(
        roundedRect: bounds, cornerWidth: cornerRadius, cornerHeight: cornerRadius, transform: nil)
    }
  }
}

