func testThePanelCastsAWindowShadow() {
  // The rail's lift comes from the WINDOW's shadow, not a SwiftUI `.shadow` — a view shadow is
  // clipped at the window bounds, and the panel is deliberately sized snug to its cards. Pinned
  // alongside `isOpaque == false` because the two look contradictory and are not: macOS derives a
  // non-opaque window's shadow from its drawn alpha, so it hugs the rail's rounded rect.
  let panel = makePanel()
  panel.isOpaque = false
  panel.hasShadow = true
  XCTAssertTrue(panel.hasShadow)
  XCTAssertFalse(panel.isOpaque)
}

input.new_string:
func testTheRailDrawsItsOwnShadowRatherThanTheWindow() {
  // Measured, not assumed: a borderless non-opaque panel casts NO system shadow — `hasShadow = true`
  // plus `invalidateShadow()` darkened nothing at 6/14/26/44pt out on any side, with glass content and
  // with a solid opaque fill alike. So the rail draws the shadow itself and the window stays shadowless.
  let panel = makePanel()
  panel.hasShadow = false
  XCTAssertFalse(panel.hasShadow, "a window shadow here would only duplicate the drawn one, squarely")
}

func testTheHaloDoesNotEatClicksMeantForTheWindowBelow() {
  // The window is bigger than the rail by `shadowMargin` on every side so the drawn shadow has room.
  // That border is empty, and a plain NSView would hit-test it — swallowing clicks that should reach
  // whatever is underneath.
  let content = HaloContentView(frame: NSRect(x: 0, y: 0, width: 400, height: 200))
  let inner = NSView(frame: content.bounds)
  inner.autoresizingMask = [.width, .height]
  content.addSubview(inner)
  let margin = SwitcherRailLayout.shadowMargin
  XCTAssertNil(
    content.hitTest(NSPoint(x: margin / 2, y: 100)), "the shadow halo must be click-through")
  XCTAssertNotNil(
    content.hitTest(NSPoint(x: 200, y: 100)), "the rail itself still takes hover and clicks")
}

// MARK: The shadow halo

func testTheWindowIsTheSlabPlusAShadowHalo() {
  let visible = CGRect(x: 0, y: 0, width: 2000, height: 1200)
  let size = L.panelSize(count: 4, visibleFrame: visible)
  XCTAssertEqual(
    size.width, L.panelWidth(count: 4, visibleFrame: visible) + L.shadowMargin * 2,
    "a drawn shadow is clipped at the window edge, so the window is bigger than the rail")
  XCTAssertEqual(size.height, L.railHeight + L.shadowMargin * 2)
}

func testOnANarrowScreenTheHaloComesOutOfTheRailNotTheScreenMargin() {
  // Otherwise the window would overhang `visibleFrame` and `panelOrigin`'s clamp would shove the rail
  // off centre — the one thing the centring work was for.
  let narrow = CGRect(x: 0, y: 0, width: 900, height: 700)
  let size = L.panelSize(count: 40, visibleFrame: narrow)
  XCTAssertLessThanOrEqual(size.width, narrow.width - L.screenMargin * 2)
  let origin = L.panelOrigin(size: size, windowFrame: narrow, visibleFrame: narrow)
  XCTAssertEqual(origin.x + size.width / 2, narrow.midX, accuracy: 0.5, "still centred")
}

