    XCTAssertNil(QuickSwitcherKey.classify(keyCode: 48, flags: [.shift]), "⇧Tab likewise")
    XCTAssertNil(QuickSwitcherKey.classify(keyCode: 48, flags: [.command]), "⌘Tab is the OS")
