import ApplicationServices
import Foundation

// Dump one menu-bar menu's items with their key equivalents + enabled state, for the app with `pid`.
// Usage: swift menu-dump.swift <pid> <menu title> [--press "<item title>"]

let args = CommandLine.arguments
guard args.count >= 3, let pid = pid_t(args[1]) else {
  FileHandle.standardError.write("usage: menu-dump.swift <pid> <menu> [--press <item>]\n".data(using: .utf8)!)
  exit(2)
}
let menuName = args[2]
let pressTitle: String? = args.count >= 5 && args[3] == "--press" ? args[4] : nil

func attr(_ element: AXUIElement, _ name: String) -> CFTypeRef? {
  var value: CFTypeRef?
  guard AXUIElementCopyAttributeValue(element, name as CFString, &value) == .success else { return nil }
  return value
}
func children(_ element: AXUIElement) -> [AXUIElement] {
  attr(element, kAXChildrenAttribute as String) as? [AXUIElement] ?? []
}
func title(_ element: AXUIElement) -> String {
  attr(element, kAXTitleAttribute as String) as? String ?? ""
}

let app = AXUIElementCreateApplication(pid)
guard let menuBar = attr(app, kAXMenuBarAttribute as String) else {
  print("NO MENU BAR (accessibility not granted?)")
  exit(1)
}
// swift-format-ignore
let bar = unsafeBitCast(menuBar, to: AXUIElement.self)
guard let menu = children(bar).first(where: { title($0) == menuName }) else {
  print("no \(menuName) menu; menus: \(children(bar).map(title))")
  exit(1)
}
guard let sub = children(menu).first else {
  print("\(menuName) has no submenu")
  exit(1)
}

let modifierNames: [(Int, String)] = [(1, "⇧"), (2, "⌥"), (4, "⌃")]
for item in children(sub) {
  let name = title(item)
  if name.isEmpty { print("  ──────────"); continue }
  let enabled = attr(item, kAXEnabledAttribute as String) as? Bool ?? false
  var chord = ""
  if let mods = attr(item, "AXMenuItemCmdModifiers") as? Int {
    // AXMenuItemCmdModifiers: bit 0 = NO command, so ⌘ is present unless bit 0 is set.
    for (bit, glyph) in modifierNames where mods & bit != 0 { chord += glyph }
    if mods & 8 == 0 { chord += "⌘" }
  }
  var key = ""
  if let ch = attr(item, "AXMenuItemCmdChar") as? String { key = ch }
  if key.isEmpty, let virt = attr(item, "AXMenuItemCmdVirtualKey") as? Int {
    key = virt == 48 ? "⇥" : "vk\(virt)"
  }
  print("  \(enabled ? "[on ]" : "[off]") \(name)\t\(chord)\(key)")
  if let pressTitle, name == pressTitle {
    let result = AXUIElementPerformAction(item, kAXPressAction as CFString)
    print("  → pressed \(name): \(result == .success ? "ok" : "\(result.rawValue)")")
  }
}

