import ApplicationServices
import Foundation

// Print every descendant with a non-empty AX identifier matching an optional filter, plus its
// selected/value state. Usage: swift ax-ids.swift <pid> [filter]
guard CommandLine.arguments.count >= 2, let pid = pid_t(CommandLine.arguments[1]) else { exit(2) }
let filter = CommandLine.arguments.count >= 3 ? CommandLine.arguments[2] : ""
let app = AXUIElementCreateApplication(pid)

func attr(_ element: AXUIElement, _ name: String) -> CFTypeRef? {
  var value: CFTypeRef?
  guard AXUIElementCopyAttributeValue(element, name as CFString, &value) == .success else { return nil }
  return value
}

func walk(_ element: AXUIElement, depth: Int) {
  if depth > 22 { return }
  let id = attr(element, kAXIdentifierAttribute as String) as? String ?? ""
  if !id.isEmpty, filter.isEmpty || id.contains(filter) {
    let role = attr(element, kAXRoleAttribute as String) as? String ?? "?"
    let title = attr(element, kAXTitleAttribute as String) as? String ?? ""
    let selected = attr(element, kAXSelectedAttribute as String) as? Bool
    let value = attr(element, kAXValueAttribute as String) as? Int
    print("\(String(repeating: " ", count: depth))\(id) [\(role)] title=\(title) selected=\(selected.map(String.init) ?? "-") value=\(value.map(String.init) ?? "-")")
  }
  for child in attr(element, kAXChildrenAttribute as String) as? [AXUIElement] ?? [] {
    walk(child, depth: depth + 1)
  }
}

for window in attr(app, kAXWindowsAttribute as String) as? [AXUIElement] ?? [] {
  walk(window, depth: 0)
}

